from collections import defaultdict

# Build adjacency to find connected components
six_positions = [(1, 7), (3, 3), (3, 11), (4, 5), (4, 18), (5, 14), (5, 20), (6, 7), (7, 11), (8, 13), (9, 0), (9, 4), (9, 8), (10, 17), (12, 11), (13, 3), (13, 18), (14, 6), (14, 14), (18, 0), (18, 5), (18, 8), (18, 13), (19, 3)]

# Check connectivity (ensure cells are adjacent including diagonals)
connections = defaultdict(list)
for i, (r1, c1) in enumerate(six_positions):
    for j, (r2, c2) in enumerate(six_positions):
        if i < j:
            if abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1:
                connections[(r1, c1)].append((r2, c2))
                connections[(r2, c2)].append((r1, c1))

# Find connected components
visited = set()
components = []
for pos in six_positions:
    if pos not in visited:
        component = []
        stack = [pos]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            component.append(curr)
            for neighbor in connections[curr]:
                if neighbor not in visited:
                    stack.append(neighbor)
        components.append(component)

print(f"Number of connected components: {len(components)}")
for i, comp in enumerate(components):
    print(f"Component {i}: {len(comp)} cells - {comp}")

